const stat=(n,label)=>'<div class="stat"><strong>'+esc(n)+'</strong><span>'+esc(label)+'</span></div>';
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,5000);}
function save(){try{localStorage.setItem(key,JSON.stringify(state));return true;}catch(e){const n=document.getElementById('storage-notice');n.textContent='Hasil belum bisa disimpan di browser. Unduh cadangan sebelum menutup halaman agar tulisanmu tidak hilang.';n.hidden=false;return false;}}
try{const raw=JSON.parse(localStorage.getItem(key)||'null');if(raw){state=K.validate(raw,C);if(raw.timer?.running&&[1200,2400,3600].includes(raw.timer.duration)&&Number.isFinite(raw.timer.end)&&state.timer){state.timer.running=true;state.timer.end=raw.timer.end;}}}catch(e){const n=document.getElementById('storage-notice');n.textContent='Cadangan di browser belum bisa dibaca. Buka file cadangan di Hasil belajar jika kamu memilikinya.';n.hidden=false;}
function go(route){if(window.LANGKAH_MODULE_CONTEXT?.navigate){window.LANGKAH_MODULE_CONTEXT.navigate(route);return;}if(location.hash==='#'+route)render();else location.hash=route;}
