const diagRefs=[['w03',0],['w05',0],['w06',0],['w10',0],['w12',0],['w13',0],['w14',0],['w15',0]];
function diagnostic(){const questions=diagRefs.map(([id,i])=>lessonMap.get(id).qs[i]);return heading('CEK AWAL · 8 SOAL','Cari titik yang perlu dilatih.','Ini cek pemahaman instruksi dan keputusan menulis. Hasilnya bukan band IELTS atau tes tingkat bahasa.')+(state.diagnostic?'<div class="notice">Hasil terakhir: <strong>'+state.diagnostic.score+'/8 jawaban tepat</strong>. '+(state.diagnostic.wrongTags.length?'Bagian untuk dilatih: '+[...new Set(state.diagnostic.wrongTags)].map(t=>C.tags[t]).join(', ')+'.':'Coba buktikan pemahamanmu lewat tulisan lengkap pada soal baru.')+'</div>':'')+'<section class="card" id="diagnostic-quiz">'+questions.map((q,i)=>questionMarkup(q,i,{answers:diagnosticAnswers,checked:false},'diagnostic')).join('')+'<div class="button-row">'+btn('Lihat saran belajar','finish-diagnostic')+link('Mulai dari dasar','lesson/w01','secondary')+'</div></section>';}
